// REQ-FX1 · Temblor de cámara al caer desde alto
// Detecta caídas de más de 15 bloques (ajustable) e introduce un temblor (screen shake)
// amortiguado en la vista al impactar contra el suelo.
//
// Tunables ajustables en runtime vía game.temblorCaida:
//   game.temblorCaida.alturaMin   (default: 15 bloques)
//   game.temblorCaida.amplitud    (default: 0.03 rad / escala de sacudida)
//   game.temblorCaida.duracion    (default: 0.5 s)
//   game.temblorCaida.frecuencia  (default: 9 Hz)
//
// API:
//   game.temblorCaida.on()
//   game.temblorCaida.off()
//   game.temblorCaida.disparar(fuerza)   // disparar temblor manual
//   game.temblorCaida.estado()

(() => {
'use strict';

let activo = false;
let origMcUpdate = null;
let origMcViewMatrix = null;

const CFG = {
  alturaMin: 15,       // bloques mínimos de caída para activar el efecto
  amplitud: 0.03,      // intensidad de giro angular
  duracion: 0.5,       // duración en segundos
  frecuencia: 9        // oscilaciones por segundo (Hz)
};

const EST = {
  maxAlturaEnAire: 0,
  estabaEnAire: false,
  tiempoImpacto: 0,
  fuerzaImpacto: 0
};

function patchedUpdate(dt){
  if(!mc.active || mc.volar || mc._intro){
    EST.estabaEnAire = false;
    if(origMcUpdate) origMcUpdate.apply(this, arguments);
    return;
  }

  const enAire = !mc.onGround;
  const y = mc.pos[1];

  if(enAire){
    if(!EST.estabaEnAire){
      EST.estabaEnAire = true;
      EST.maxAlturaEnAire = y;
    } else if(y > EST.maxAlturaEnAire){
      EST.maxAlturaEnAire = y;
    }
  }

  if(origMcUpdate) origMcUpdate.apply(this, arguments);

  // Comprobar si acaba de aterrizar en este tick
  if(EST.estabaEnAire && mc.onGround){
    const caidaBloques = EST.maxAlturaEnAire - mc.pos[1];
    if(caidaBloques >= CFG.alturaMin){
      // Fuerza proporcional a cuánto sobrepasa la altura mínima (factor 1.0 a 2.5)
      const ratio = Math.min(2.5, Math.max(1.0, caidaBloques / CFG.alturaMin));
      EST.tiempoImpacto = performance.now();
      EST.fuerzaImpacto = ratio;
    }
    EST.estabaEnAire = false;
    EST.maxAlturaEnAire = 0;
  }
}

function patchedViewMatrix(){
  let mat = origMcViewMatrix ? origMcViewMatrix.apply(this, arguments) : null;
  if(!mat) return mat;

  if(EST.tiempoImpacto > 0){
    const elapsed = (performance.now() - EST.tiempoImpacto) / 1000;
    if(elapsed < CFG.duracion){
      // Decaimiento exponencial suave (1 -> 0)
      const progreso = elapsed / CFG.duracion;
      const decay = Math.pow(1 - progreso, 2);
      // Oscilación senoidal amortiguada
      const angulo = elapsed * CFG.frecuencia * Math.PI * 2;
      const shakePitch = Math.sin(angulo) * CFG.amplitud * EST.fuerzaImpacto * decay;
      const shakeRoll  = Math.cos(angulo * 0.7) * (CFG.amplitud * 0.6) * EST.fuerzaImpacto * decay;
      const shakeY     = Math.sin(angulo * 1.5) * (CFG.amplitud * 0.4) * EST.fuerzaImpacto * decay;

      // Aplicar vibración a la matriz de vista
      if(typeof mat4 !== 'undefined'){
        mat = mat4.mul(mat4.rotZ(shakeRoll), mat);
        mat = mat4.mul(mat4.rotX(shakePitch), mat);
        mat = mat4.mul(mat4.translate(0, -shakeY, 0), mat);
      }
    } else {
      EST.tiempoImpacto = 0;
      EST.fuerzaImpacto = 0;
    }
  }

  return mat;
}

function instalar(){
  if(window.mcUpdate && !origMcUpdate){
    origMcUpdate = window.mcUpdate;
    window.mcUpdate = patchedUpdate;
  }
  if(window.mcViewMatrix && !origMcViewMatrix){
    origMcViewMatrix = window.mcViewMatrix;
    window.mcViewMatrix = patchedViewMatrix;
  }
  activo = true;
  console.log('✅ REQ-FX1: temblor de cámara al caer instalado');
}

function desinstalar(){
  if(origMcUpdate){ window.mcUpdate = origMcUpdate; origMcUpdate = null; }
  if(origMcViewMatrix){ window.mcViewMatrix = origMcViewMatrix; origMcViewMatrix = null; }
  activo = false;
  console.log('❌ REQ-FX1: temblor de cámara desinstalado');
}

const API = {
  get alturaMin(){ return CFG.alturaMin; },
  set alturaMin(v){ CFG.alturaMin = Math.max(1, +v || 15); },
  get amplitud(){ return CFG.amplitud; },
  set amplitud(v){ CFG.amplitud = Math.max(0.001, +v || 0.03); },
  get duracion(){ return CFG.duracion; },
  set duracion(v){ CFG.duracion = Math.max(0.05, +v || 0.5); },
  get frecuencia(){ return CFG.frecuencia; },
  set frecuencia(v){ CFG.frecuencia = Math.max(1, +v || 9); },
  on(){ if(!activo) instalar(); return 'REQ-FX1 activado'; },
  off(){ if(activo) desinstalar(); return 'REQ-FX1 desactivado'; },
  disparar(fuerza = 1.0){
    EST.tiempoImpacto = performance.now();
    EST.fuerzaImpacto = fuerza;
    return 'Temblor disparado con fuerza ' + fuerza;
  },
  estado(){
    return 'REQ-FX1: ' + (activo ? 'ACTIVO' : 'inactivo') + ' [alturaMin=' + CFG.alturaMin + ', amp=' + CFG.amplitud + ', dur=' + CFG.duracion + 's, freq=' + CFG.frecuencia + 'Hz]';
  }
};

game.temblorCaida = API;
API.on();
})();
